 phases:W=>[{c:["A>G","F>H"],cls:"h1",txt:"AF = CD, AK = CE and FK = DE. The triangles AFK and CDE have three equal sides."},{ang:[["C","D","E"],["A","F","K"]],cls:"g",txt:"Proposition 8: three equal sides mean equal angles. So the angle at A equals the angle at C."}],
